-- CI-only schema subset derived from the supplied metadata. No business data or credentials.
CREATE TABLE public.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),full_name varchar(100) NOT NULL,email varchar(255) NOT NULL,role varchar(12) NOT NULL,status varchar(16) NOT NULL,email_verified_at timestamptz,session_version int NOT NULL DEFAULT 0);
CREATE TABLE public.coach_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),registration_review_status text);
CREATE TABLE public.programs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(100) NOT NULL,description text,min_age_years smallint,max_age_years smallint,weekly_sessions smallint,display_fee bigint,status varchar(12) NOT NULL DEFAULT 'aktif' CHECK(status IN('aktif','arsip')));
CREATE UNIQUE INDEX uq_program_name ON programs(lower(btrim(name)));
CREATE TABLE public.players(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE REFERENCES users(id),student_code varchar(30),full_name varchar(100) NOT NULL,gender varchar(16) NOT NULL,birth_date date NOT NULL,status varchar(12) NOT NULL);
CREATE TABLE public.registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),player_id uuid NOT NULL REFERENCES players(id),program_id uuid NOT NULL REFERENCES programs(id),status varchar(16) NOT NULL);
CREATE TABLE public.classes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),program_id uuid REFERENCES programs(id),name varchar(80) NOT NULL,min_age_years smallint,max_age_years smallint,gender_category varchar(12) NOT NULL DEFAULT 'campuran' CHECK(gender_category IN('campuran','putra','putri')),capacity integer CHECK(capacity>0),status varchar(12) NOT NULL DEFAULT 'aktif' CHECK(status IN('aktif','arsip')),created_by uuid REFERENCES users(id),CHECK(min_age_years IS NULL OR max_age_years IS NULL OR min_age_years<=max_age_years));
CREATE UNIQUE INDEX uq_class_name ON classes(lower(btrim(name)));
CREATE TABLE public.coach_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),class_id uuid NOT NULL REFERENCES classes(id),coach_user_id uuid NOT NULL REFERENCES users(id),assignment_type varchar(12) NOT NULL DEFAULT 'utama' CHECK(assignment_type IN('utama','asisten')),start_date date NOT NULL,end_date date,assigned_by uuid REFERENCES users(id),CHECK(end_date IS NULL OR end_date>=start_date),UNIQUE(class_id,coach_user_id,start_date));
CREATE UNIQUE INDEX uq_head ON coach_assignments(class_id) WHERE end_date IS NULL AND assignment_type='utama';
CREATE TABLE public.class_enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),player_id uuid NOT NULL REFERENCES players(id),class_id uuid NOT NULL REFERENCES classes(id),start_date date NOT NULL,end_date date,assigned_by uuid REFERENCES users(id),CHECK(end_date IS NULL OR end_date>=start_date),UNIQUE(player_id,class_id,start_date));
CREATE UNIQUE INDEX uq_active_player ON class_enrollments(player_id) WHERE end_date IS NULL;
CREATE TABLE public.training_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),class_id uuid NOT NULL REFERENCES classes(id),session_type varchar(16) NOT NULL CHECK(session_type IN('latihan','pertandingan')),title varchar(150) NOT NULL,session_date date NOT NULL,start_time time NOT NULL,end_time time NOT NULL CHECK(end_time>start_time),venue varchar(150) NOT NULL,status varchar(16) NOT NULL DEFAULT 'terjadwal' CHECK(status IN('terjadwal','selesai','dibatalkan')),notes text,created_by uuid REFERENCES users(id));
CREATE TABLE public.attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES training_sessions(id),player_id uuid NOT NULL REFERENCES players(id),status varchar(8) NOT NULL CHECK(status IN('hadir','izin','sakit','alpa')),notes text,recorded_by uuid REFERENCES users(id),recorded_at timestamptz DEFAULT now() NOT NULL,UNIQUE(session_id,player_id));
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,metadata jsonb);

-- Profile-only additions matching local metadata; fixture is isolated.
ALTER TABLE users ADD COLUMN profile_photo_jpeg bytea CHECK(octet_length(profile_photo_jpeg)<=262144);
ALTER TABLE coach_profiles ADD COLUMN phone varchar(25), ADD COLUMN registration_whatsapp text, ADD COLUMN license_name varchar(120);
ALTER TABLE players ADD COLUMN birth_place varchar(100),ADD COLUMN school_name varchar(150),ADD COLUMN guardian_name varchar(100) NOT NULL DEFAULT 'Wali Uji',ADD COLUMN contact_phone varchar(25),ADD COLUMN address text,ADD COLUMN jersey_size varchar(5);

CREATE TABLE public.assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),player_id uuid NOT NULL REFERENCES players(id),class_id uuid NOT NULL REFERENCES classes(id),assessment_month date NOT NULL CHECK(extract(day FROM assessment_month)=1),technique smallint NOT NULL CHECK(technique BETWEEN 1 AND 10),physical smallint NOT NULL CHECK(physical BETWEEN 1 AND 10),tactical smallint NOT NULL CHECK(tactical BETWEEN 1 AND 10),discipline smallint NOT NULL CHECK(discipline BETWEEN 1 AND 10),notes varchar(500),assessed_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(player_id,class_id,assessment_month));
CREATE TABLE public.announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),target_class_id uuid REFERENCES classes(id),category varchar(30) NOT NULL DEFAULT 'Info',title varchar(150) NOT NULL,body text NOT NULL,audience varchar(16) NOT NULL CHECK(audience IN('semua','pemain','pelatih')),expires_at timestamptz,created_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.announcement_reads(announcement_id uuid REFERENCES announcements(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,read_at timestamptz DEFAULT now(),PRIMARY KEY(announcement_id,user_id));
CREATE TABLE public.news(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title varchar(180) NOT NULL,slug varchar(210) NOT NULL UNIQUE,category varchar(40) NOT NULL,summary text,content text NOT NULL,cover_path text,status varchar(12) NOT NULL CHECK(status IN('draft','terbit','arsip')),published_at timestamptz,author_user_id uuid REFERENCES users(id),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());

-- Phase 10 fixture: match uploaded finance metadata, plus private proof migration.
CREATE TABLE public.fee_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(30) NOT NULL UNIQUE,name varchar(100) NOT NULL,default_amount bigint CHECK(default_amount>=0),description text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_number varchar(40) NOT NULL UNIQUE,player_id uuid NOT NULL REFERENCES players(id) ON DELETE RESTRICT,registration_id uuid REFERENCES registrations(id) ON DELETE RESTRICT,invoice_type varchar(20) NOT NULL CHECK(invoice_type IN('pendaftaran','bulanan','per_latihan','lainnya')),period_month date CHECK(period_month IS NULL OR extract(day FROM period_month)=1),issued_on date NOT NULL DEFAULT CURRENT_DATE,due_on date,total_amount bigint NOT NULL DEFAULT 0 CHECK(total_amount>=0),status varchar(16) NOT NULL DEFAULT 'diterbitkan' CHECK(status IN('draft','diterbitkan','sebagian','lunas','dibatalkan')),notes text,created_by uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(invoice_type<>'bulanan' OR period_month IS NOT NULL));
CREATE UNIQUE INDEX uq_bnr_monthly_invoice ON invoices(player_id,period_month) WHERE invoice_type='bulanan' AND status<>'dibatalkan';
CREATE UNIQUE INDEX uq_bnr_registration_invoice ON invoices(registration_id) WHERE invoice_type='pendaftaran' AND registration_id IS NOT NULL AND status<>'dibatalkan';
CREATE TABLE public.invoice_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES invoices(id) ON DELETE RESTRICT,fee_type_id uuid REFERENCES fee_types(id) ON DELETE RESTRICT,training_session_id uuid REFERENCES training_sessions(id) ON DELETE RESTRICT,description varchar(200) NOT NULL,quantity integer NOT NULL DEFAULT 1 CHECK(quantity>0),unit_price bigint NOT NULL CHECK(unit_price>=0),line_total bigint GENERATED ALWAYS AS (quantity::bigint*unit_price) STORED,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.payment_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),method_type varchar(12) NOT NULL CHECK(method_type IN('bank','ewallet','qris')),provider_name varchar(100) NOT NULL,account_number varchar(80),account_holder varchar(120),qris_image_path text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES invoices(id) ON DELETE RESTRICT,payment_account_id uuid REFERENCES payment_accounts(id) ON DELETE RESTRICT,amount bigint NOT NULL CHECK(amount>0),payment_method varchar(16) NOT NULL CHECK(payment_method IN('transfer_bank','ewallet','qris','tunai')),proof_file_path text,proof_jpeg bytea CHECK(octet_length(proof_jpeg)<=1048576),payment_reference varchar(120) UNIQUE,status varchar(16) NOT NULL DEFAULT 'menunggu' CHECK(status IN('menunggu','terverifikasi','ditolak')),submitted_at timestamptz NOT NULL DEFAULT now(),paid_at timestamptz,verified_by uuid REFERENCES users(id) ON DELETE SET NULL,verified_at timestamptz,rejection_reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'ditolak' OR NULLIF(btrim(rejection_reason),'') IS NOT NULL),CHECK(status<>'terverifikasi' OR verified_at IS NOT NULL));
